#include <stdio.h>
#include <stdlib.h>

typedef struct {
    int parent;
    int rank;
} DSU;

int find(DSU *dsu, int x) {
    if (dsu[x].parent != x)
        dsu[x].parent = find(dsu, dsu[x].parent);
    return dsu[x].parent;
}

void unite(DSU *dsu, int a, int b, int *components) {
    int ra = find(dsu, a);
    int rb = find(dsu, b);
    if (ra == rb) return;

    if (dsu[ra].rank < dsu[rb].rank) {
        dsu[ra].parent = rb;
    } else if (dsu[ra].rank > dsu[rb].rank) {
        dsu[rb].parent = ra;
    } else {
        dsu[rb].parent = ra;
        dsu[ra].rank++;
    }
    (*components)--;
}

int main(void) {
    int N, M;
    if (scanf("%d %d", &N, &M) != 2) return 0;

    DSU *dsu = (DSU *)malloc((N + 1) * sizeof(DSU));
    if (!dsu) return 0;

    for (int i = 1; i <= N; i++) {
        dsu[i].parent = i;
        dsu[i].rank = 0;
    }

    int municipalities = N;

    for (int i = 0; i < M; i++) {
        int a, b;
        scanf("%d %d", &a, &b);
        unite(dsu, a, b, &municipalities);
    }

    int diff = N - municipalities;
    if (diff < 0) diff = -diff;
    printf("%d\n", diff);

    free(dsu);
    return 0;
}

